//! Print the Markdown tool catalog (`docs/tools.md`) from the server's tool routers.
use flybase_mcp::server::FlyBaseServer;

fn main() {
    let router = FlyBaseServer::all_tool_routers();
    println!(
        "# FlyBase MCP tool catalog\n\nGenerated by `cargo run --bin tool-catalog`. Do not edit by hand.\n"
    );
    let mut tools = router.list_all();
    tools.sort_by(|a, b| a.name.cmp(&b.name));
    for t in tools {
        let schema = serde_json::to_string_pretty(t.input_schema.as_ref()).unwrap_or_default();
        println!(
            "## `{}`\n\n{}\n\n```json\n{}\n```\n",
            t.name,
            t.description.as_deref().unwrap_or(""),
            schema
        );
    }
}
